CREATE POLICY "forum_avatars_owner_read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'forum-avatars' AND (storage.foldername(name))[1] = (select auth.uid())::text);
CREATE POLICY "forum_avatars_owner_insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'forum-avatars' AND (storage.foldername(name))[1] = (select auth.uid())::text);
CREATE POLICY "forum_avatars_owner_update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'forum-avatars' AND (storage.foldername(name))[1] = (select auth.uid())::text) WITH CHECK (bucket_id = 'forum-avatars' AND (storage.foldername(name))[1] = (select auth.uid())::text);
CREATE POLICY "forum_avatars_owner_delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'forum-avatars' AND (storage.foldername(name))[1] = (select auth.uid())::text);